<div class="page-heading"><h1><?=e(t('คำสั่งซื้อ BP-'))?><?=sprintf('%06d',$o['id'])?></h1><p><?=e($o['created_at'])?></p><div class="order-badges"><?=order_badge($o)?> <?=payment_badge($o)?></div></div>
<?php $stage=order_stage($o);$steps=in_array($o['payment_method'],['BANK','PROMPTPAY'],true)?['pending','awaiting_payment','payment_review','paid','preparing','shipped','delivered']:['pending','confirmed','preparing','shipped','delivered'];$position=array_search($stage,$steps,true); ?>
<?php if($stage==='cancelled'): ?><div class="notice"><?=e(t('ยกเลิกคำสั่งซื้อแล้ว'))?><?=$o['payment_status']==='paid'?' · การคืนเงินต้องดำเนินการและบันทึกแยกต่างหาก':''?></div><?php else: ?><ol class="order-timeline" aria-label="<?=e(t('ความคืบหน้าคำสั่งซื้อ'))?>"><?php foreach($steps as $index=>$step): ?><li class="<?=$position!==false&&$index<=$position?'is-complete':''?>" <?=$step===$stage?'aria-current="step"':''?>><span><?=$index+1?></span><?=e(t(ORDER_STAGES[$step]))?></li><?php endforeach ?></ol><?php endif ?>
<div class="two-col"><section class="panel"><h2><?=e(t('รายการสินค้า'))?></h2><?php foreach(q('SELECT * FROM order_items WHERE order_id=?',[$o['id']]) as $item): ?><p><?=e(localized_name($item))?> <?=e(($item['variant_color']??'').' '.($item['variant_size']??''))?> × <?=(int)$item['quantity']?> <strong><?=money($item['line_total']??(cents($item['price'])*$item['quantity']/100))?></strong></p><?php endforeach ?><hr><p><?=e(t('รวมสินค้า'))?> <?=money($o['subtotal'])?></p><?php if(cents($o['product_discount']??0)+cents($o['coupon_discount']??0)>0): ?><p><?=e(t('ส่วนลดสินค้าและคูปอง −'))?> <?=money((cents($o['product_discount']??0)+cents($o['coupon_discount']??0))/100)?></p><?php endif ?><p><?=e(t('ค่าจัดส่งสุทธิ'))?> <?=money($o['shipping'])?></p><h2><?=e(t('ยอดรวม'))?> <?=money($o['total'])?></h2><p><?=payment_method_label($o)?></p><?=payment_badge($o)?><?php if($o['payment_method']==='COD'): ?><p><?=e(t('ชำระเงินเมื่อได้รับสินค้า'))?></p><?php elseif(!empty($o['bank_account_number'])): ?><dl class="bank-details"><dt><?=e(t('ธนาคาร'))?></dt><dd><?=e($o['bank_name'])?></dd><dt><?=e(t('ชื่อบัญชี'))?></dt><dd><?=e($o['bank_account_name'])?></dd><dt><?=e(t('เลขบัญชี'))?></dt><dd><span data-account-number><?=e($o['bank_account_number'])?></span> <button type="button" class="secondary" data-copy-account><?=e(t('คัดลอก'))?></button></dd></dl><p class="payment-help"><?=e(t('ข้อมูลบัญชี ณ เวลาสั่งซื้อ ยืนยันชำระเงินเมื่อผู้ดูแลตรวจยอดเข้าจริงแล้วเท่านั้น'))?></p><?php endif ?></section>
<section class="panel"><h2><?=e(t('ข้อมูลจัดส่ง'))?></h2><p><?=e($o['recipient'])?> · <?=e($o['phone'])?></p><p><?=delivery_location_html($o['address'])?> <?=e($o['subdistrict'])?> <?=e($o['district'])?> <?=e($o['province'])?> <?=e($o['postcode'])?></p><?php if(!empty($o['map_url'])): ?><p><?=delivery_location_html($o['map_url'])?></p><?php endif ?><?php if(!empty($o['address_note'])): ?><p><?=e(t('จุดสังเกต:'))?> <?=nl2br(e($o['address_note']))?></p><?php endif ?><?php if($o['latitude']!==null&&$o['longitude']!==null): ?><p><?=e(t('พิกัด'))?> <?=e($o['latitude'])?>, <?=e($o['longitude'])?> <a target="_blank" rel="noopener noreferrer" href="https://www.openstreetmap.org/?mlat=<?=e($o['latitude'])?>&amp;mlon=<?=e($o['longitude'])?>#map=17/<?=e($o['latitude'])?>/<?=e($o['longitude'])?>"><?=e(t('เปิดหมุดจัดส่ง'))?></a></p><?php endif ?><p><?=e(t('หมายเหตุ:'))?> <?=e($o['note'])?></p><hr><h3><?=e(t('ติดตามพัสดุ'))?></h3><?php if(!empty($o['package_weight'])): ?><p><?=e(t('น้ำหนักพัสดุ (กก.):'))?> <?=e($o['package_weight'])?> · <?=e($o['package_dimensions'])?></p><?php endif;if(!empty($o['shipped_at'])): ?><p><?=e(t('วันจัดส่ง:'))?> <?=e($o['shipped_at'])?></p><?php endif;if(!empty($o['delivered_at'])): ?><p><?=e(t('วันส่งสำเร็จ:'))?> <?=e($o['delivered_at'])?></p><?php endif ?><?php if(!empty($o['tracking_number'])): ?><p><?=e(t('บริษัทขนส่ง:'))?> <?=e($o['carrier'])?></p><p><?=e(t('เลขพัสดุ:'))?> <strong><?=e($o['tracking_number'])?></strong></p><?php else: ?><p><?=e(t('ยังไม่มีเลขติดตามพัสดุ'))?></p><?php endif ?></section></div>
<?php if(in_array($o['payment_method'],['BANK','PROMPTPAY'],true)): ?><section class="panel order-slips"><h2><?=e(t('หลักฐานการโอนเงิน'))?></h2><?php $slips=q('SELECT * FROM order_slips WHERE order_id=? ORDER BY id DESC',[$o['id']])->fetchAll();if(!$slips): ?><p><?=e(t('ยังไม่มีหลักฐาน'))?></p><?php endif;foreach($slips as $slip): ?><article class="slip-record"><?php if(!empty($slip['duplicate_warning'])): ?><p class="error"><?=e(t($slip['duplicate_warning']))?></p><?php endif ?><p><?=e($slip['created_at'])?> · <?=e(['pending_review'=>'รอตรวจสอบ','approved'=>'ผ่านการตรวจสอบ','rejected'=>'ไม่ผ่านการตรวจสอบ'][$slip['status']])?></p><a href="<?=url('payment_slip.php?id='.$slip['id'])?>" target="_blank" rel="noopener noreferrer"><?=e(t('เปิดดูสลิป #'))?><?=$slip['id']?></a><?php if($slip['rejection_reason']): ?><p class="error"><?=e(t('เหตุผล:'))?> <?=e($slip['rejection_reason'])?></p><?php endif ?></article><?php endforeach ?></section><?php endif ?>
<section class="panel order-history"><h2><?=e(t('ประวัติความคืบหน้า'))?></h2><?php $events=q('SELECT ev.*,u.name actor_name FROM order_events ev LEFT JOIN users u ON u.id=ev.actor_id WHERE order_id=? ORDER BY ev.id DESC',[$o['id']])->fetchAll();if(!$events): ?><p><?=e(t('คำสั่งซื้อเดิมยังไม่มีประวัติในระบบใหม่'))?></p><?php endif ?><ol><?php foreach($events as $event): ?><li><time><?=e($event['created_at'])?></time><strong><?=e(STATUSES[$event['order_status']]??$event['order_status'])?> · <?=e(PAYMENT_STATUSES[$event['payment_status']]??$event['payment_status'])?></strong><p><?=e(t_message($event['note']))?></p><small><?=e(t('ผู้ดำเนินการ:'))?> <?=e($event['actor_name']??'ระบบ')?></small></li><?php endforeach ?></ol></section>

<?php if(isset($u)&&($u['role']??'')!=='admin'): ?><p><a href="<?=url('addresses.php?from_order='.$o['id'].'#address-form')?>"><?=e(t('ตรวจสอบและบันทึกที่อยู่จากคำสั่งซื้อนี้'))?></a></p><?php endif ?>

